"""Weekly timesheet rows built from a list of shifts."""

from typing import Dict, Iterable, List

from hourglass.errors import ProjectError
from hourglass.models import Shift

def _add(totals: Dict[str, list], shift: Shift) -> None:
    if not shift.worker.strip():
        raise ProjectError("shift has no worker name")
    entry = totals.setdefault(shift.worker, [0, 0])
    entry[0] += 1
    entry[1] += shift.span.minutes

def _line(name: str, count: int, minutes: int) -> str:
    hours = minutes / 60
    return f"{name}: {count} shifts, {hours:.1f}h"

def timesheet_lines(shifts: Iterable[Shift]) -> List[str]:
    """One line per worker, busiest first."""
    totals = {}
    for shift in shifts:
        _add(totals, shift)
    if not totals:
        raise ProjectError("no shifts given")
    rank = sorted(totals, key=lambda name: -totals[name][1])
    return [_line(name, *totals[name]) for name in rank]

