# owner: platform
import unittest

from hourglass.errors import ProjectError
from hourglass.models import Shift
from hourglass.parsing import parse_span
from hourglass.timesheet import timesheet_lines

def make(worker, day, text):
    return Shift(worker, day, parse_span(text))

def sample():
    return [
        make("Ana", "mon", "09:00-10:00"),
        make("Brisa", "mon", "09:00-13:30"),
        make("Ana", "tue", "09:00-10:30")
    ]

class TimesheetTests(unittest.TestCase):
    def test_busiest_first(self):
        expected = [
            "Brisa: 1 shifts, 4.5h",
            "Ana: 2 shifts, 2.5h"
        ]
        result = timesheet_lines(sample())
        self.assertEqual(result, expected)

    def test_empty(self):
        with self.assertRaises(ProjectError):
            timesheet_lines([])

    def test_blank_worker(self):
        blank = make(" ", "mon", "09:00-10:00")
        with self.assertRaises(ProjectError):
            timesheet_lines([blank])
